import {calculateProductCosts} from './product-cost-math.mjs';
for(const form of document.querySelectorAll('[data-product-quote-form]')){const mode=form.elements.mode,unit=form.elements.unit,amount=form.elements.materialPerUnit,waste=form.elements.wastePercent;const update=()=>{const ready=mode.value==='ready';if(ready){unit.value='unit';amount.value='1';waste.value='0';}amount.readOnly=ready;waste.readOnly=ready;};mode.addEventListener('change',()=>{if(mode.value==='self'&&unit.value==='unit')unit.value='kg';update();});update();}
const form=document.querySelector('[data-product-cost-scenario]'),target=document.querySelector('[data-cost-results]'),source=document.querySelector('[data-product-cost-quotes]');
if(form&&target&&source){const quotes=JSON.parse(source.content.textContent),money=v=>new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP'}).format(v);form.addEventListener('input',()=>{const s=Object.fromEntries(new FormData(form)),result=calculateProductCosts(quotes.find(q=>q.id===s.quoteId),s);target.replaceChildren();if(!result.complete){const p=document.createElement('p');p.textContent=result.reason;target.append(p);return;}const dl=document.createElement('dl');dl.className='product-cost-metrics';for(const [name,value] of [['Repeat cost / unit',money(result.repeatUnitCost)],['Net selling price',money(result.netSellingPrice)],['Gross profit / unit',money(result.grossProfit)],['Gross margin',result.grossMargin.toFixed(1)+'%'],['Contribution / unit',money(result.contribution)],['Contribution margin',result.contributionMargin.toFixed(1)+'%'],['Initial cash required',money(result.initialCash)],['First order cost / unit',money(result.firstOrderCostPerUnit)],['One-off setup',money(result.setup)],['Purchase quantity',result.purchaseQuantity.toFixed(4)],['Unused material / stock',result.unusedMaterial.toFixed(4)],['Order contribution after setup',money(result.contributionAfterSetup)]]){const div=document.createElement('div'),dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=name;dd.textContent=value;div.append(dt,dd);dl.append(div);}target.append(dl);});}
